#!/bin/bash
# Auto-upgrade script generated by macro2clippy!

echo "🔧 Upgrading codebase with manifest tracking..."

# Step 1: Add manifest macros to all binaries
echo "📝 Adding manifest imports..."
find src/bin -name '*.rs' -exec sed -i '1i use crate::manifest_macros::*;' {} \;

# Step 2: Replace file operations with tracking versions
echo "📊 Converting file operations to tracked versions..."
find . -name '*.rs' -exec sed -i 's/std::fs::read_to_string(/track_file_read!(/g' {} \;
find . -name '*.rs' -exec sed -i 's/std::fs::write(/track_file_write!(/g' {} \;

# Step 3: Add manifest reporting to each binary
echo "📋 Adding manifest reporting to binaries..."
for file in src/bin/*.rs; do
    binary_name=$(basename "$file" .rs)
    echo "report_manifest!(\"$binary_name\");" >> "$file"
done

# Step 4: Run clippy to fix issues
echo "🔍 Running clippy fixes..."
cargo clippy --fix --allow-dirty --allow-staged

# Step 5: Generate bootstrap manifest
echo "🚀 Generating bootstrap manifest..."
cargo run --bin split-decls-rs -- bootstrap --generate-manifest

echo "✅ Upgrade complete! Check bootstrap_manifest.toml"
